  const legacyTarget=Number(legacyProposal?.task_id||legacyProposal?.target_task_id||legacyTask?.id||0),scheduleConflict=action&&unique.length===1&&Boolean(legacyTask||legacyProposal)&&(legacyTarget===0||legacyTarget!==Number(planTask?.id||0));
