  if(vm.subjectRef.type==='action')return vm.entity.status==='done'?{purpose:'readonly',label:'回看结果',prompt:'本次跟进已完成，实际结果和下一步保留。'}:{purpose:'activity',label:'保存进展',prompt:'这次见面或跟进进展到了哪一步？'};
