  if(p.settling_state==='paused')return operation('resume',`本轮协调已暂缓；${p.active_schedule?'原有效日程继续。':''}请明确选择恢复后的推进方式。`);
  if(p.settling_state==='abandoned')return operation('start_reschedule',`本轮协调已放弃；${p.active_schedule?'原有效日程继续。':''}需要重新协调时再明确开启。`);
