  if(p.date_intent==='unknown')return supplement('这个日期是准备联系或执行活动，还是希望在此前定下时间？也可以一并补充具体安排。');
  if(codes.includes('decision_mode_unknown')||codes.includes('missing_content'))return supplement('这是你自己决定的行动，还是准备和对方约定？也可以一并说清这次要做什么。');
