function restoreDetailEditing(root,saved,{anchor=false}={}){const details=new Map(Array.from(root.querySelectorAll('details')).map(node=>[detailDisclosureKey(node),node]));for(const item of saved.expanded||[])if(details.has(item.key))details.get(item.key).open=item.open;if(saved.scroll?.isConnected)saved.scroll.scrollTop=saved.scrollTop;const focus=saved.focus?.isConnected?saved.focus:detailFindFocus(root,saved.focusIdentity);if(focus){focus.focus({preventScroll:true});if(saved.selection)focus.setSelectionRange?.(...saved.selection);if(anchor&&saved.scroll?.isConnected&&typeof saved.anchorTop==='number')saved.scroll.scrollTop+=focus.getBoundingClientRect().top-saved.anchorTop;}}
function detailCacheCurrent(ref=detailPresentedRef()){if(!ref)return null;const content=$('#detail-content'),root=$('.detail-progress')||content,session=root.detailSession;if(session)preserveDetailPurpose(session);const saved={ref:{...ref},csrf:state.csrf,nodes:Array.from(content.childNodes||content.children||[]),detail:session?.subjectRef.type==='action'?{type:'record',id:ref.id,data:session.vm.dto}:session?.subjectRef.type==='arrangement'?{type:'arrangement',id:ref.id,revision:session.vm.entity.revision}:detailPresentedState||state.detail,editing:preserveDetailEditing(root),root};detailViewCache.set(`${state.csrf}:${detailReferenceKey(ref)}`,saved);return saved;}
function pushDetailReturnContext(ref){if(!ref||!ref.type||ref.id===null||ref.id===undefined)return false;const key=detailReferenceKey(ref);for(let i=detailReturnStack.length-1;i>=0;i--)if(detailReferenceKey(detailReturnStack[i])===key)detailReturnStack.splice(i,1);detailReturnStack.push({type:ref.type,id:ref.id,csrf:state.csrf});while(detailReturnStack.length>5)detailReturnStack.shift();return true;}
function detailBeforeOpenDialog(kind){if(kind!=='detail')return;const current=detailPresentedRef(),dialog=$('#detail-dialog');if(detailReturning)return;if(!dialog?.open&&!suspendedDetail){detailReturnStack.length=0;return;}if(current){detailCacheCurrent(current);const next=state.detail?.type==='record'&&state.detail.data?.record?.kind==='action'?{type:'action',id:Number(state.detail.id)}:state.detail?{type:state.detail.type,id:state.detail.id}:null;if(next&&detailReferenceKey(next)!==detailReferenceKey(current))pushDetailReturnContext(current);}}
function detailAfterOpenDialog(kind){if(kind!=='detail')return;detailPresentedState=state.detail;const root=$('.detail-progress');detailPresentedSubject=root?.detailSession?{...root.detailSession.subjectRef}:state.detail?{type:state.detail.type,id:state.detail.id}:null;for(let i=detailReturnStack.length-1;i>=0;i--)if(detailReturnStack[i].csrf!==state.csrf||detailReferenceKey(detailReturnStack[i])===detailReferenceKey(detailPresentedSubject||{}))detailReturnStack.splice(i,1);attachDetailReturn();}
function attachDetailReturn(){const content=$('#detail-content');content?.querySelector('[data-detail-return]')?.remove();const target=detailReturnStack.at(-1);if(!target||target.csrf!==state.csrf)return;const header=content.querySelector('.dialog-header');if(!header)return;const button=document.createElement('button');button.type='button';button.className='text-button detail-return';button.dataset.detailReturn='';button.dataset.detailOwnedButton='';button.textContent=target.type==='action'?'返回待办详情':target.type==='arrangement'?'返回安排详情':'返回上一处';header.querySelector('div')?.prepend(button);}
async function detailReadReturn(ref){if(ref.type==='action'||ref.type==='record'){try{return await api(`/api/records/${Number(ref.id)}`);}catch(problem){if(problem.status!==404)throw problem;const kept=await api(`/api/records/${Number(ref.id)}/lifecycle`);return {record:kept.record,readonly:true,visibility:kept.visibility};}}if(ref.type==='arrangement'){try{return (await api(`/api/secretary/plans/${Number(ref.id)}`)).plan;}catch(problem){if(problem.status!==404)throw problem;const cached=detailViewCache.get(`${state.csrf}:${detailReferenceKey(ref)}`),plan=cached?.root?.detailSession?.vm.dto;if(!Number(plan?.record_id))throw problem;await api(`/api/records/${Number(plan.record_id)}/lifecycle`);return {...plan,readonly:true,source_visible:false,source_hidden:true,arrangement:{...arrangementProjection(plan),source_visible:false,source_hidden:true}};}}if(ref.type==='material')return api(`/api/materials/${encodeURIComponent(ref.id)}`);if(ref.type==='visit')return api(`/api/visits/${encodeURIComponent(ref.id)}`);if(ref.type==='customer')return api(`/api/customers/${Number(ref.id)}`);const saved=detailViewCache.get(`${state.csrf}:${detailReferenceKey(ref)}`),scope=saved?.detail?.data?.secretary?.scope;if(Number(scope?.record_id||scope?.source_record_id))await api(`/api/records/${Number(scope.record_id||scope.source_record_id)}`);return null;}
async function restoreDetailReturnContext(){const ref=detailReturnStack.at(-1);if(!ref||ref.csrf!==state.csrf)return false;const saved=detailViewCache.get(`${state.csrf}:${detailReferenceKey(ref)}`);if(!saved)return false;detailCacheCurrent();const epoch=++detailRestoreEpoch,csrf=state.csrf,intent=state.dialogIntentGeneration=Number(state.dialogIntentGeneration||0)+1,dialog=$('#detail-dialog');const dto=await detailReadReturn(ref);if(epoch!==detailRestoreEpoch||!state.authenticated||state.csrf!==csrf||Number(state.dialogIntentGeneration||0)!==intent||!dialog.open)return false;detailReturnStack.pop();detailReturning=true;try{const content=$('#detail-content');content.replaceChildren(...saved.nodes);state.detail=saved.detail;detailPresentedState=saved.detail;detailPresentedSubject={type:ref.type,id:ref.id};dialog.classList.toggle('customer-detail-dialog',Boolean($('.customer-dialog-shell',dialog)));const session=saved.root.detailSession;if(session){session.epoch=++detailSessionSequence;if(dto){const combined=ref.type==='action'?{...session.vm.dto,...dto}:dto;session.vm=buildDetailViewModel(session.subjectRef,combined);if(ref.type==='action')state.detail.data=combined;else arrangementPlans.set(Number(ref.id),combined);await refreshDetailSubject(session.subjectRef,{dto:combined});}}restoreDetailEditing(saved.root,saved.editing);attachDetailReturn();resumeDetailProcessing(saved.root);return true;}finally{detailReturning=false;}}
function wireDetailReadControls(root,vm){for(const node of root.querySelectorAll('[data-detail-zone="D"] .schedule-editor form')){const section=node.closest('details');node.remove();if(vm.visible){const link=document.createElement('button');link.type='button';link.className='text-button';link.dataset.detailPurpose='legacy_schedule';link.dataset.detailOwnedButton='';link.textContent='在本次推进中补充具体时间';section?.append(link);}}for(const node of root.querySelectorAll('[data-complete-outcome],[data-edit-action-terms]')){const outcome=node.hasAttribute('data-complete-outcome');node.removeAttribute(outcome?'data-complete-outcome':'data-edit-action-terms');node.dataset.detailPurpose=outcome?'outcome':'terms';node.dataset.detailOwnedButton='';}if(vm.subjectRef.type==='arrangement')for(const node of root.querySelectorAll('[data-arrangement-operation],[data-arrangement-select],[data-arrangement-suggest-check]')){const op=node.dataset.arrangementOperation||(node.dataset.arrangementSuggestCheck?'set_check':'select_candidate');if(node.dataset.arrangementSelect)node.dataset.detailCandidate=node.dataset.arrangementSelect;for(const key of ['data-arrangement-operation','data-arrangement-select','data-arrangement-suggest-check'])node.removeAttribute(key);node.dataset.detailPurpose=op==='update_progress'?'progress':'decision';node.dataset.detailOperation=op==='update_progress'?'':op;node.dataset.detailOwnedButton='';const choice=op==='update_progress'?'progress':'decision:'+op;if(!detailPurposeOptions(vm).some(([value])=>value===choice))node.remove();}}
function updateDetailReadSections(session,dto){const root=session.root,saved=preserveDetailEditing(root),holder=document.createElement('div');holder.innerHTML=session.subjectRef.type==='action'?detailActionHTML(dto,typeof recordScheduleHTML==='function'?recordScheduleHTML(dto):'',(dto.activities||[]).map(a=>`<li><time>${e(formatDate(a.created_at,true))}</time><p>${e(a.content)}</p>${a.child_record_id?`<button class="inline-link" data-record="${Number(a.child_record_id)}">查看本次交流整理</button>`:''}</li>`).join('')):arrangementDetailHTML(dto);for(const zone of ['B','D','E']){const target=root.querySelector(`[data-detail-zone="${zone}"]`),next=holder.querySelector(`[data-detail-zone="${zone}"]`);if(!target||!next)continue;const drafts=Array.from(target.querySelectorAll('form')).filter(form=>typeof dirtyForm==='function'&&dirtyForm(form));target.innerHTML=next.innerHTML;for(const form of drafts){const replacement=Array.from(target.querySelectorAll('form')).find(node=>node.id===form.id);replacement?.replaceWith(form);if(!session.vm.visible)form.querySelector('[type="submit"]')?.setAttribute('disabled','');}}
 const title=root.querySelector('.detail-progress-title');if(title)title.textContent=session.vm.entity.title;const eyebrow=root.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent=session.subjectRef.type==='action'?`待办 · ${recordStatus(session.vm.entity)}`:`安排 · ${arrangementStateLabels[session.vm.entity.settling_state]||'待核对'}`;wireDetailReadControls(root,session.vm);restoreDetailEditing(root,saved,{anchor:true});
}
document.addEventListener('click',async event=>{const button=event.target.closest?.('[data-detail-return]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();if(button.disabled)return;button.disabled=true;try{await restoreDetailReturnContext();}catch(problem){notify('原位置与草稿保留，暂时无法读取返回对象：'+problem.message,true);}finally{if(button.isConnected)button.disabled=false;}},true);

function detailDisclosureKey(node){const path=[];let current=node;while(current&&!current.classList?.contains('detail-progress')){if(current.matches?.('details'))path.unshift(current.dataset.arrangementSection||current.dataset.detailDisclosure||(current.querySelector('summary')?.textContent||'').replace(/\s*·.*$/,'').replace(/\d+/g,'#').trim());if(current.dataset?.detailZone)path.unshift(current.dataset.detailZone);current=current.parentElement;}return path.join('/');}

function resumeDetailProcessing(root){const session=root?.detailSession;if(!session||!detailSessionCurrent(session))return;const pending=Number(session.pendingTurnId)||(session.vm.entity.turns||session.vm.dto.turns||[]).filter(turn=>['queued','processing'].includes(turn.status)).sort((a,b)=>Number(b.id)-Number(a.id))[0]?.id;if(pending)detailPollTurn(session,pending);}

async function findDetailRecordPlans(session){const epoch=session.epoch,recordId=session.subjectRef.id,found=new Map(),rows=[];let offset=0;while(detailSessionCurrent(session)&&session.epoch===epoch){const page=await api(`/api/secretary/arrangements?view=all&state=all&limit=200&offset=${offset}`),items=page.items||[];rows.push(...items);offset+=items.length;if(!items.length||offset>=Number(page.total??offset)||items.length<200)break;}for(let start=0;start<rows.length;start+=4){if(!detailSessionCurrent(session)||session.epoch!==epoch)return;const results=await Promise.allSettled(rows.slice(start,start+4).map(async row=>{const id=Number(row.plan_id);if(!id)return;const plan=(await api(`/api/secretary/plans/${id}`)).plan;if(Number(plan.id||plan.plan_id)!==id)throw new Error('关联安排返回了不同对象，请重新读取。');if(Number(plan.record_id)===recordId||(plan.turns||[]).some(turn=>Number(turn.plan_id)===id&&Number(turn.record_id)===recordId))found.set(id,plan);}));for(const result of results)if(result.status==='rejected')throw result.reason;}if(!detailSessionCurrent(session)||session.epoch!==epoch)return;const dto={...session.vm.dto,secretary_plans:[...found.values()],secretary_plan:null};await refreshDetailSubject(session.subjectRef,{dto});if(!detailSessionCurrent(session)||session.epoch!==epoch)return;session.associationScanComplete=true;notify(`已按记录与原话的真实编号核对：${found.size} 次关联活动。`);}
document.addEventListener('click',async event=>{const button=event.target.closest?.('button[data-detail-find-plans]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const session=button.closest('.detail-progress')?.detailSession;if(!detailSessionCurrent(session)||button.disabled)return;button.disabled=true;try{await findDetailRecordPlans(session);}catch(problem){if(detailSessionCurrent(session))notify('关联活动尚未查全，已知记录和输入继续保留：'+problem.message,true);}finally{if(button.isConnected)button.disabled=false;}},true);

function updateDetailPurposeChoices(session){const select=session.root.querySelector('[data-detail-purpose-choice]');if(!select)return;const wanted=session.purpose==='decision'?'decision:'+session.operation:session.purpose,choices=detailPurposeOptions(session.vm);select.innerHTML=choices.map(([value,label])=>`<option value="${e(value)}" ${value===wanted?'selected':''}>${e(label)}</option>`).join('')+(choices.some(([value])=>value===wanted)?'':`<option value="${e(wanted)}" selected>原草稿 · 当前需核对</option>`);}

function revealDetailEditing(){const field=document.activeElement,root=field?.closest?.('.detail-progress'),scroll=root?.querySelector('.detail-progress-scroll');if(!scroll||!['INPUT','TEXTAREA','SELECT'].includes(field.tagName))return;const rect=field.getBoundingClientRect(),bounds=scroll.getBoundingClientRect();if(rect.bottom>bounds.bottom-12)scroll.scrollTop+=rect.bottom-bounds.bottom+12;else if(rect.top<bounds.top+12)scroll.scrollTop-=bounds.top+12-rect.top;}
if(typeof window!=='undefined'){window.addEventListener('resize',()=>requestAnimationFrame(revealDetailEditing));window.visualViewport?.addEventListener('resize',()=>requestAnimationFrame(revealDetailEditing));}
document.addEventListener('focusin',event=>{if(event.target.closest?.('.detail-progress'))requestAnimationFrame(revealDetailEditing);});

async function detailRevalidateAssociations(session,dto){const recordId=session.subjectRef.id,ids=[...new Set([...session.vm.plans.map(plan=>Number(plan.id||plan.plan_id)),Number(dto.secretary_plan?.id||dto.secretary_plan?.plan_id)].filter(Boolean))],plans=[];for(let start=0;start<ids.length;start+=4){const results=await Promise.all(ids.slice(start,start+4).map(async id=>{const plan=(await api(`/api/secretary/plans/${id}`)).plan;if(Number(plan.id||plan.plan_id)!==id)throw new Error('关联活动返回了不同对象，已核对的活动选择仍保留。');if(Number(plan.record_id)===recordId||(plan.turns||[]).some(turn=>Number(turn.plan_id)===id&&Number(turn.record_id)===recordId))return plan;return null;}));plans.push(...results.filter(Boolean));}return {...dto,secretary_plan:null,secretary_plans:plans};}

function detailFocusIdentity(node){return {tag:node.tagName,id:node.id||'',name:node.getAttribute?.('name')||'',zone:node.closest?.('[data-detail-zone]')?.dataset.detailZone||'',disclosure:node.matches?.('summary')?detailDisclosureKey(node.closest('details')):'',data:Object.entries(node.dataset||{}).filter(([key])=>!key.startsWith('detailOwned')),text:(node.textContent||'').trim()};}
function detailFindFocus(root,identity){if(!identity)return null;const nodes=Array.from(root.querySelectorAll('button,input,textarea,select,summary,a'));return nodes.find(node=>node.tagName===identity.tag&&(!identity.zone||node.closest('[data-detail-zone]')?.dataset.detailZone===identity.zone)&&(identity.id?node.id===identity.id:identity.name?node.getAttribute('name')===identity.name:identity.disclosure?detailDisclosureKey(node.closest('details'))===identity.disclosure:identity.data.length?identity.data.every(([key,value])=>node.dataset[key]===value):(node.textContent||'').trim()===identity.text))||null;}

function detailPurposePrompt(vm,purpose,operation){if(!vm.visible||purpose==='readonly')return vm.focus.prompt;const prompts={activity:'这次见面或跟进进展到了哪一步？',organize:'记下这次交流，保存后再整理可跟进的下一步。',outcome:'先核对全部影响，再填写本次实际结果并明确完成。',terms:'分别核对负责人、完成期限和检查点；这些资料不会移动正式日程。',legacy_schedule:'补充这条待办的执行时间，保存后仍需明确确认提案。',progress:'记下实际进展，保留当前推进点与安排状态。'};if(prompts[purpose])return prompts[purpose];if(purpose==='decision'){const operations={set_deadline:'这一次安排需要何时前定下来？执行日程保持原时间。',set_check:'下次何时再问、核对什么？这不是活动的执行时间。',pause:'本轮先暂停协调；已生效的日程继续保留。',resume:'明确恢复这一轮协调，重新核对需要的推进点。',abandon_coordination:'放弃本轮协调；原有效日程继续，事项和项目不因此结束。',start_reschedule:'商量新的执行时间；新方案落实前原日程继续。',continue_set_time:'日期已经定下，继续在同一次活动中确定具体钟点。',withdraw_execution:'只撤销当前有效日程，仍可继续协调新的时间。',cancel_activity:'取消这一次活动的日程和提示，事项与项目继续保留。',select_candidate:'先保存所选方案，再核对其他缺口；选择不代表已经约好。'};if(operations[operation])return operations[operation];}return vm.focus.prompt;}
function detailOperationSubmitLabel(operation){return {set_deadline:'保存确定期限',set_check:'保存下一推进点',pause:'暂缓本轮协调',resume:'恢复本轮协调',abandon_coordination:'放弃本轮协调',start_reschedule:'开始商量改期',continue_set_time:'继续确定钟点',withdraw_execution:'撤销当前日程'}[operation]||'';}
